 const [session,setSession]=useState<any>(null),[company,setCompany]=useState<any>(null),[memberships,setMemberships]=useState<any[]>([]),[companyName,setCompanyName]=useState('My Factory'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[authMsg,setAuthMsg]=useState(''),[busy,setBusy]=useState(false),[syncMsg,setSyncMsg]=useState('');
