 function persistLocal(next:Rec[]){setRows(next);localStorage.setItem(localKey,JSON.stringify(next))}
 async function saveRecord(){if(!canWrite){setSyncMsg('Your workspace role is read-only. Contact an administrator for edit access.');return;}if(!form.title.trim()){alert(t.required);return;}const r:Rec={id:editing?.id||uid(),module:mod,title:form.title.trim(),status:form.status||'Open',record_date:form.record_date||new Date().toISOString().slice(0,10),value:Number(form.value)||0,notes:form.notes||'',details:form.details||{}};
 if(configured&&session&&company&&supabase){const payload={...r,company_id:company.company_id};const{error}=await supabase.from('records').upsert(payload);if(error){setSyncMsg(error.message);return;}await loadRows()}else{persistLocal(editing?[r,...rows.filter(x=>x.id!==editing.id)]:[r,...rows])}
 setShow(false);setEditing(null);setForm({title:'',status:'Open',record_date:new Date().toISOString().slice(0,10),value:0,notes:'',details:{}});setSyncMsg(t.saved)}
 async function removeRecord(r:Rec){if(!canDelete){setSyncMsg('Only workspace administrators and managers can delete records.');return;}if(!confirm('Delete this record?'))return;if(configured&&session&&company){const{error}=await supabase!.from('records').delete().eq('id',r.id);if(error){setSyncMsg(error.message);return;}loadRows()}else persistLocal(rows.filter(x=>x.id!==r.id))}
 function openNew(){if(!canWrite){setSyncMsg('Your workspace role is read-only. Contact an administrator for edit access.');return;}setEditing(null);setForm({title:'',status:'Open',record_date:new Date().toISOString().slice(0,10),value:0,notes:'',details:{}});setShow(true)}
