 add('Executive summary',[{Metric:'Total records',Value:dataGovernance.records},{Metric:'Required-field completeness (%)',Value:dataGovernance.missingRate===null?'Not available':dataGovernance.missingRate},{Metric:'Missing required fields',Value:dataGovernance.missing.length},{Metric:'Invalid numeric / date values',Value:dataGovernance.invalid.length},{Metric:'Potential duplicate BOM references',Value:dataGovernance.duplicates.length},{Metric:'Production references not matched to BOM',Value:dataGovernance.orphanProduction.length}],'No records available');
